const results = {};
const token = $("Call 'Read_token'").first().json["Access Token"];

for (const item of $input.all()) {
  const shipId = item.json.shipping?.id;
  const orderId = item.json.id;
  const packId = item.json.pack_id || null;
  const orderItems = item.json.order_items || [];

  let bonusFlex = 0;
  if (shipId && token) {
    try {
      const shipRes = await this.helpers.httpRequest({
        method: 'GET',
        url: `https://api.mercadolibre.com/shipments/${shipId}`,
        headers: { Authorization: `Bearer ${token}` },
        json: true
      });
      if (shipRes && shipRes.logistic_type === 'self_service') {
        const costRes = await this.helpers.httpRequest({
          method: 'GET',
          url: `https://api.mercadolibre.com/shipments/${shipId}/costs`,
          headers: { Authorization: `Bearer ${token}` },
          json: true
        });
        bonusFlex = Number(costRes?.senders?.[0]?.save) || 0;
      }
    } catch (e) {
      // En caso de error, bonusFlex permanece en 0
    }
  }

  const pagos = item.json.payments || [];
  const pagosAprobadosEnOrden = pagos
    .filter(p => p.status === 'approved')
    .map(p => p.id);

  if (!results[shipId]) {
    results[shipId] = {
      order_ids: [orderId],
      shipping_id: shipId,
      pack_id: packId,
      ids_pagos: pagosAprobadosEnOrden,
      resumen_productos: "",
      items_detalle: [],
      bonus_flex: bonusFlex
    };
  } else {
    if (!results[shipId].order_ids.includes(orderId)) {
      results[shipId].order_ids.push(orderId);
    }
    pagosAprobadosEnOrden.forEach(id => {
      if (!results[shipId].ids_pagos.includes(id)) {
        results[shipId].ids_pagos.push(id);
      }
    });
  }

  for (const producto of orderItems) {
    const productName = producto.item.title;
    const quantity = producto.quantity;
    const separador = results[shipId].resumen_productos === "" ? "" : " + ";
    results[shipId].resumen_productos += `${separador}${productName} (x${quantity})`;

    results[shipId].items_detalle.push({
      order_id_origen: orderId,
      mla: producto.item.id,
      nombre: productName,
      variante: producto.item.variation_id || 'Sin variante',
      cantidad: quantity
    });
  }
}

const finalOutput = [];
for (const group of Object.values(results)) {
  if (group.ids_pagos.length === 0) continue;
  for (const paymentId of group.ids_pagos) {
    finalOutput.push({
      json: {
        ...group,
        id_pago_aprobado: paymentId,
        order_id: group.order_ids.join(', ')
      }
    });
  }
}

return finalOutput;

const results = {};

for (const item of $input.all()) {
  // Capturamos los datos principales
  const shipId = item.json.shipping.id;
  const orderId = item.json.id; // <--- Aquí obtenemos el ID de la orden
  const orderItem = item.json.order_items[0];
  const productName = orderItem.item.title;
  const quantity = orderItem.quantity;
  const mlaId = orderItem.item.id;
  const variationId = orderItem.item.variation_id || 'Sin variante';

  // Si es la primera vez que vemos este envío, creamos el objeto
  if (!results[shipId]) {
    results[shipId] = {
      order_id: orderId, // <--- Lo agregamos al resultado
      shipping_id: shipId,
      pack_id: item.json.pack_id,
      resumen_productos: `${productName} (x${quantity})`,
      items_detalle: [{
        mla: mlaId,
        nombre: productName,
        variante: variationId,
        cantidad: quantity
      }]
    };
  } else {
    // Si el envío ya existe (porque hay más productos), solo acumulamos
    results[shipId].resumen_productos += ` + ${productName} (x${quantity})`;

    // Agregamos el nuevo producto a la lista detallada
    results[shipId].items_detalle.push({
      mla: mlaId,
      nombre: productName,
      variante: variationId,
      cantidad: quantity
    });
  }
}

// Convertimos el objeto agrupado en una lista simple para n8n
return Object.values(results);

// 1. Obtenemos la fecha del Webhook (ej: "2026-04-21")
const fechaRecibida = $('Webhook').item.json.body.fecha;

// 2. Inicio: 00:01 AM Argentina (03:01 UTC)
const from = `${fechaRecibida}T03:01:00.000Z`;

// 3. Calculamos el final de ESE MISMO día en Argentina (23:59:59).
// En UTC, esto equivale a las 02:59:59 del día siguiente.
const fechaFin = new Date(fechaRecibida + 'T03:00:00Z');
fechaFin.setUTCDate(fechaFin.getUTCDate() + 1);
fechaFin.setUTCSeconds(fechaFin.getUTCSeconds() - 1);
const finDelDiaUTC = fechaFin.toISOString();

// 4. Obtenemos el "ahora" real
const ahora = new Date().toISOString();

// 5. El límite 'to' será el final del día elegido, 
// a menos que sea hoy, en cuyo caso usamos el 'ahora'.
const to = (ahora < finDelDiaUTC) ? ahora : finDelDiaUTC;

return {
  from,
  to
};

// 1. Obtenemos el total de ventas que encontró el nodo "obtener total"
// Usamos || 0 por si la API devuelve el campo vacío
const total = $("obtener total").item.json.paging.total || 0;
const limit = 50;
const offsets = [];

// 2. Si no hay ventas en esa fecha, devolvemos una lista vacía.
// Esto hará que el flujo se detenga aquí de forma limpia.
if (total === 0) {
  return [];
}

// 3. Creamos las "páginas" (offsets). 
// Si hay 10 ventas, generará 1 página (offset 0). 
// Si hay 60, generará 2 (offset 0 y offset 50).
for (let i = 0; i < total; i += limit) {
  offsets.push({ offset: i });
}

return offsets;

